	class := searchVerifyStem(subject.testPath)
	return &SearchVerifyCommand{
		Command:     fmt.Sprintf("./gradlew %stest --tests '%s'", project, class),
		Targets:     subject.testPath,
		DerivedFrom: manifest + " + gradlew + " + subject.testEvidence + " class",
	}
}

